-- Apply using Supabase SQL editor or CLI. Disable public Auth signup separately.
create table public.admin_profiles(id uuid primary key references auth.users(id) on delete restrict, role text not null check(role in ('owner','administrator','content_manager','recruitment_manager','inquiry_manager')));
alter table public.admin_profiles enable row level security;
create policy own_profile on public.admin_profiles for select to authenticated using (id=auth.uid());
create function public.admin_role() returns text language sql stable security definer set search_path=public as $$ select role from public.admin_profiles where id=auth.uid() $$;
revoke all on function public.admin_role() from public; grant execute on function public.admin_role() to authenticated;
create table public.projects(id text primary key, status text not null default 'draft', approved boolean not null default false, data jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.projects enable row level security;
create index projects_status_idx on public.projects(status);
create policy public_read on public.projects for select to anon,authenticated using (status='published' and approved and data->>'image' like 'https://%' and data->>'image' not like '%/placeholders/%');
create policy admin_read on public.projects for select to authenticated using (public.admin_role() in ('owner','administrator','content_manager'));
create policy admin_insert on public.projects for insert to authenticated with check (public.admin_role() in ('owner','administrator','content_manager'));
create policy admin_update on public.projects for update to authenticated using (public.admin_role() in ('owner','administrator','content_manager')) with check (public.admin_role() in ('owner','administrator','content_manager'));
alter table public.projects add constraint approved_publish check(status <> 'published' or (approved and coalesce(data->>'image','') like 'https://%' and data->>'image' not like '%/placeholders/%'));
