create function public.audit_change() returns trigger language plpgsql security definer set search_path=public as $$ begin new.updated_at=now(); insert into public.activity(id,status,data) values(gen_random_uuid()::text,'recorded',jsonb_build_object('action',TG_OP||' '||TG_TABLE_NAME,'record_id',new.id,'actor',auth.uid()));return new;end $$;
create trigger audit_projects before insert or update on public.projects for each row execute function public.audit_change();
create trigger audit_services before insert or update on public.services for each row execute function public.audit_change();
create trigger audit_industries before insert or update on public.industries for each row execute function public.audit_change();
create trigger audit_testimonials before insert or update on public.testimonials for each row execute function public.audit_change();
create trigger audit_careers before insert or update on public.careers for each row execute function public.audit_change();
create trigger audit_media before insert or update on public.media for each row execute function public.audit_change();
create trigger audit_settings before insert or update on public.settings for each row execute function public.audit_change();
create trigger audit_quotes before insert or update on public.quotes for each row execute function public.audit_change();
create trigger audit_applications before insert or update on public.applications for each row execute function public.audit_change();
create trigger audit_contacts before insert or update on public.contacts for each row execute function public.audit_change();
create table public.rate_limits(client text primary key, window_start timestamptz not null, hits integer not null);
alter table public.rate_limits enable row level security;
create function public.check_rate(client text) returns boolean language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into public.rate_limits values(md5(client),now(),1) on conflict on constraint rate_limits_pkey do update set hits=case when rate_limits.window_start<now()-interval '1 hour' then 1 else rate_limits.hits+1 end,window_start=case when rate_limits.window_start<now()-interval '1 hour' then now() else rate_limits.window_start end returning hits into n;return n<=10;end $$;
revoke all on function public.check_rate(text) from public;grant execute on function public.check_rate(text) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('project-media','project-media',false,10000000,array['image/jpeg','image/png','image/webp']),('private-attachments','private-attachments',false,10000000,array['application/pdf']);
create policy content_media_read on storage.objects for select to authenticated using(bucket_id='project-media' and public.admin_role() in ('owner','administrator','content_manager'));
create policy content_media_insert on storage.objects for insert to authenticated with check(bucket_id='project-media' and public.admin_role() in ('owner','administrator','content_manager'));
create policy private_attachment_read on storage.objects for select to authenticated using(bucket_id='private-attachments' and public.admin_role() in ('owner','administrator'));
